--- main ---
#include "diagnostics.h"
#include "grammar_ast.h"
#include "markup_lexer.h"
#include "recognizer.h"

#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    const char *grammar_path;
    const char *input_path;
    const char *start_name;
    bool have_grammar;
    bool have_input;
    bool have_start;
    bool have_stats;
} CliOptions;

static int command_line_error(const PbnfcDiagnosticContext *diagnostics,
                              const char *detail)
{
    (void)pbnfc_diagnostic_emit(diagnostics, detail, NULL);
    return 2;
}

static bool is_option(const char *argument)
{
    return argument[0] == '-' && argument[1] == '-';
}

static bool read_file(const char *path,
                      const char *kind,
                      char **source_out,
                      size_t *length_out,
                      const PbnfcDiagnosticContext *diagnostics)
{
    FILE *stream;
    char *source;
    size_t capacity = 4096U;
    size_t length = 0U;

    stream = fopen(path, "rb");
    if (stream == NULL) {
        (void)pbnfc_diagnostic_emit(diagnostics, kind, NULL);
        return false;
    }
    source = (char *)malloc(capacity + 1U);
    if (source == NULL) {
        (void)fclose(stream);
        (void)pbnfc_diagnostic_emit(diagnostics, "out of memory reading file", NULL);
        return false;
    }
    for (;;) {
        size_t count = fread(source + length, 1U, capacity - length, stream);

        length += count;
        if (count == 0U) {
            if (ferror(stream)) {
                free(source);
                (void)fclose(stream);
                (void)pbnfc_diagnostic_emit(diagnostics, kind, NULL);
                return false;
            }
            break;
        }
        if (length == capacity) {
            size_t next_capacity;
            char *next_source;

            if (capacity > (size_t)-1 / 2U ||
                capacity * 2U + 1U < capacity * 2U) {
                free(source);
                (void)fclose(stream);
                (void)pbnfc_diagnostic_emit(diagnostics,
                                            "file is too large",
                                            NULL);
                return false;
            }
            next_capacity = capacity * 2U;
            next_source = (char *)realloc(source, next_capacity + 1U);
            if (next_source == NULL) {
                free(source);
                (void)fclose(stream);
                (void)pbnfc_diagnostic_emit(diagnostics,
                                            "out of memory reading file",
                                            NULL);
                return false;
            }
            source = next_source;
            capacity = next_capacity;
        }
    }
    source[length] = '\0';
    (void)fclose(stream);
    *source_out = source;
    *length_out = length;
    return true;
}

static bool lex_input(const char *source,
                      size_t length,
                      const PbnfcDiagnosticContext *diagnostics,
                      PbnfcMarkupToken **tokens_out,
                      size_t *count_out)
{
    PbnfcMarkupLexer lexer;
    PbnfcMarkupToken token;
    PbnfcMarkupToken *tokens = NULL;
    size_t count = 0U;
    size_t capacity = 0U;

    pbnfc_markup_lexer_init(&lexer, source, length, diagnostics);
    for (;;) {
        if (!pbnfc_markup_lexer_next(&lexer, &token)) {
            free(tokens);
            return false;
        }
        if (token.kind == PBNFC_MARKUP_TOKEN_EOF) {
            break;
        }
        if (count == capacity) {
            size_t next_capacity = capacity == 0U ? 16U : capacity * 2U;
            PbnfcMarkupToken *next_tokens;

            if (next_capacity < capacity ||
                next_capacity > (size_t)-1 / sizeof(*tokens)) {
                free(tokens);
                (void)pbnfc_diagnostic_emit(diagnostics,
                                            "input has too many tokens",
                                            NULL);
                return false;
            }
            next_tokens = (PbnfcMarkupToken *)realloc(
                tokens, next_capacity * sizeof(*tokens));
            if (next_tokens == NULL) {
                free(tokens);
                (void)pbnfc_diagnostic_emit(diagnostics,
                                            "out of memory lexing input",
                                            NULL);
                return false;
            }
            tokens = next_tokens;
            capacity = next_capacity;
        }
        tokens[count] = token;
        ++count;
    }
    *tokens_out = tokens;
    *count_out = count;
    return true;
}

static void print_stats(const PbnfcRecognitionStats *stats)
{
    size_t worker_index;

    (void)fprintf(stdout,
                  " workers=%zu active_workers=%zu rounds=%zu tasks=",
                  stats->workers,
                  stats->active_workers,
                  stats->rounds);
    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        if (worker_index != 0U) {
            (void)fputc(',', stdout);
        }
        (void)fprintf(stdout, "%zu", stats->tasks[worker_index]);
    }
}

static int parse_options(int argc,
                         char **argv,
                         CliOptions *options,
                         const PbnfcDiagnosticContext *diagnostics)
{
    int index;

    for (index = 1; index < argc; ++index) {
        const char *argument = argv[index];

        if (strcmp(argument, "--grammar") == 0) {
            if (options->have_grammar) {
                return command_line_error(diagnostics, "duplicate option --grammar");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --grammar");
            }
            options->grammar_path = argv[++index];
            options->have_grammar = true;
        } else if (strcmp(argument, "--input") == 0) {
            if (options->have_input) {
                return command_line_error(diagnostics, "duplicate option --input");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --input");
            }
            options->input_path = argv[++index];
            options->have_input = true;
        } else if (strcmp(argument, "--start") == 0) {
            if (options->have_start) {
                return command_line_error(diagnostics, "duplicate option --start");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --start");
            }
            options->start_name = argv[++index];
            options->have_start = true;
        } else if (strcmp(argument, "--stats") == 0) {
            if (options->have_stats) {
                return command_line_error(diagnostics, "duplicate option --stats");
            }
            options->have_stats = true;
        } else if (is_option(argument)) {
            return command_line_error(diagnostics, "unknown option");
        } else {
            return command_line_error(diagnostics, "unexpected positional argument");
        }
    }

    if (!options->have_grammar) {
        return command_line_error(diagnostics, "missing required option --grammar");
    }
    if (!options->have_input) {
        return command_line_error(diagnostics, "missing required option --input");
    }

    return 0;
}

int main(int argc, char **argv)
{
    CliOptions options = {0};
    PbnfcDiagnosticContext diagnostics;
    char *grammar_source = NULL;
    char *input_source = NULL;
    size_t grammar_length = 0U;
    size_t input_length = 0U;
    PbnfcGrammar *grammar = NULL;
    PbnfcMarkupToken *tokens = NULL;
    size_t token_count = 0U;
    PbnfcRecognitionStats stats;
    PbnfcRecognitionResult result;
    int exit_code = 2;

    pbnfc_diagnostic_context_init(&diagnostics, stderr);

    (void)pthread_self();

    if (parse_options(argc, argv, &options, &diagnostics) != 0) {
        return 2;
    }

    if (!read_file(options.grammar_path,
                   "unable to read grammar file",
                   &grammar_source,
                   &grammar_length,
                   &diagnostics)) {
        goto cleanup;
    }
    if (!pbnfc_grammar_parse(grammar_source,
                             grammar_length,
                             &diagnostics,
                             &grammar) ||
        !pbnfc_grammar_validate(grammar, &diagnostics)) {
        goto cleanup;
    }
    if (!read_file(options.input_path,
                   "unable to read input file",
                   &input_source,
                   &input_length,
                   &diagnostics) ||
        !lex_input(input_source,
                   input_length,
                   &diagnostics,
                   &tokens,
                   &token_count)) {
        goto cleanup;
    }

    result = pbnfc_recognize_parallel_with_diagnostics(grammar,
                                                       tokens,
                                                       token_count,
                                                       options.start_name,
                                                       &diagnostics,
                                                       &stats);
    if (result == PBNFC_RECOGNITION_REJECTED) {
        exit_code = 1;
        goto cleanup;
    }
    if (result != PBNFC_RECOGNITION_ACCEPTED) {
        (void)pbnfc_diagnostic_emit(&diagnostics,
                                    "parallel recognizer failed",
                                    NULL);
        goto cleanup;
    }
    (void)fprintf(stdout, "ACCEPT tokens=%zu", token_count);
    if (options.have_stats) {
        print_stats(&stats);
    }
    (void)fputc('\n', stdout);
    exit_code = 0;

cleanup:
    free(tokens);
    pbnfc_grammar_free(grammar);
    free(input_source);
    free(grammar_source);
    return exit_code;
}
--- lexer ---
#include "markup_lexer.h"

static bool is_layout_space(unsigned char character)
{
    return character == (unsigned char)' ' ||
           character == (unsigned char)'\t' ||
           character == (unsigned char)'\v' ||
           character == (unsigned char)'\f' ||
           character == (unsigned char)'\r' ||
           character == (unsigned char)'\n';
}

static bool is_identifier_start(unsigned char character)
{
    return (character >= (unsigned char)'A' &&
            character <= (unsigned char)'Z') ||
           (character >= (unsigned char)'a' &&
            character <= (unsigned char)'z') ||
           character == (unsigned char)'_' ||
           character == (unsigned char)':';
}

static bool is_identifier_part(unsigned char character)
{
    return is_identifier_start(character) ||
           (character >= (unsigned char)'0' &&
            character <= (unsigned char)'9') ||
           character == (unsigned char)'.' ||
           character == (unsigned char)'-';
}

static unsigned char current_character(const PbnfcMarkupLexer *lexer)
{
    return (unsigned char)lexer->source[lexer->offset];
}

static void advance_one(PbnfcMarkupLexer *lexer)
{
    unsigned char character = current_character(lexer);

    ++lexer->offset;
    if (character == (unsigned char)'\n') {
        ++lexer->line;
        lexer->column = 1U;
    } else {
        ++lexer->column;
    }
}

static void skip_layout_space(PbnfcMarkupLexer *lexer)
{
    while (lexer->offset < lexer->length &&
           is_layout_space(current_character(lexer))) {
        advance_one(lexer);
    }
}

static bool text_has_nonspace(const PbnfcMarkupLexer *lexer, size_t start)
{
    size_t offset = start;

    while (offset < lexer->offset) {
        if (!is_layout_space((unsigned char)lexer->source[offset])) {
            return true;
        }
        ++offset;
    }
    return false;
}

static void set_token(PbnfcMarkupToken *token,
                      PbnfcMarkupTokenKind kind,
                      PbnfcLocation location,
                      const char *text,
                      size_t length)
{
    token->kind = kind;
    token->location = location;
    token->text = text;
    token->length = length;
}

static bool emit_error(PbnfcMarkupLexer *lexer,
                       const PbnfcLocation *location,
                       const char *detail)
{
    lexer->failed = true;
    if (lexer->diagnostics != NULL) {
        (void)pbnfc_diagnostic_emit(lexer->diagnostics, detail, location);
    }
    return false;
}

static bool fail_at_current(PbnfcMarkupLexer *lexer, const char *detail)
{
    PbnfcLocation location;

    location.byte_offset = lexer->offset;
    location.line = lexer->line;
    location.column = lexer->column;
    return emit_error(lexer, &location, detail);
}

static bool tag_state_allows_end(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE ||
           state == PBNFC_MARKUP_TAG_AFTER_CLOSE_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_SELF_CLOSE_END;
}

static bool tag_state_allows_slash(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_EXPECT_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE;
}

static bool tag_state_allows_identifier(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_EXPECT_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_VALUE ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE;
}

static bool read_string(PbnfcMarkupLexer *lexer,
                        PbnfcMarkupToken *token,
                        PbnfcLocation location)
{
    const size_t start = lexer->offset;
    const unsigned char quote = current_character(lexer);

    advance_one(lexer);
    while (lexer->offset < lexer->length) {
        unsigned char character = current_character(lexer);

        if (character >= 0x80U) {
            return fail_at_current(lexer, "invalid markup byte");
        }
        if (character == (unsigned char)'\\') {
            advance_one(lexer);
            if (lexer->offset == lexer->length) {
                return emit_error(lexer,
                                  &location,
                                  "unterminated markup quoted value");
            }
            character = current_character(lexer);
            if (character != quote && character != (unsigned char)'\\') {
                return emit_error(lexer,
                                  &location,
                                  "invalid markup value escape");
            }
            advance_one(lexer);
            continue;
        }
        if (character == quote) {
            advance_one(lexer);
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_VALUE;
            set_token(token,
                      PBNFC_MARKUP_TOKEN_STRING,
                      location,
                      lexer->source + start,
                      lexer->offset - start);
            return true;
        }
        advance_one(lexer);
    }

    return emit_error(lexer,
                      &location,
                      "unterminated markup quoted value");
}

void pbnfc_markup_lexer_init(PbnfcMarkupLexer *lexer,
                             const char *source,
                             size_t length,
                             const PbnfcDiagnosticContext *diagnostics)
{
    if (lexer == NULL) {
        return;
    }
    lexer->source = source;
    lexer->length = length;
    lexer->offset = 0U;
    lexer->line = 1U;
    lexer->column = 1U;
    lexer->in_tag = false;
    lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_NAME;
    lexer->diagnostics = diagnostics;
    lexer->failed = false;
}

bool pbnfc_markup_lexer_next(PbnfcMarkupLexer *lexer,
                             PbnfcMarkupToken *token)
{
    PbnfcLocation location;
    size_t start;
    unsigned char character;

    if (lexer == NULL || token == NULL || lexer->failed) {
        return false;
    }
    if (lexer->source == NULL && lexer->length != 0U) {
        return fail_at_current(lexer, "markup source is unavailable");
    }

    if (lexer->in_tag) {
        skip_layout_space(lexer);
    } else {
        for (;;) {
            start = lexer->offset;
            location.byte_offset = start;
            location.line = lexer->line;
            location.column = lexer->column;

            while (lexer->offset < lexer->length &&
                   current_character(lexer) != (unsigned char)'<') {
                advance_one(lexer);
            }
            if (lexer->offset != start) {
                if (text_has_nonspace(lexer, start)) {
                    set_token(token,
                              PBNFC_MARKUP_TOKEN_TEXT,
                              location,
                              lexer->source + start,
                              lexer->offset - start);
                    return true;
                }
                continue;
            }
            break;
        }
    }

    if (lexer->offset == lexer->length) {
        if (lexer->in_tag) {
            return fail_at_current(lexer, "unterminated markup tag");
        }
        location.byte_offset = lexer->offset;
        location.line = lexer->line;
        location.column = lexer->column;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_EOF,
                  location,
                  lexer->source == NULL ? NULL : lexer->source + lexer->offset,
                  0U);
        return true;
    }

    start = lexer->offset;
    location.byte_offset = start;
    location.line = lexer->line;
    location.column = lexer->column;
    character = current_character(lexer);

    if (!lexer->in_tag) {
        if (character != (unsigned char)'<') {
            return fail_at_current(lexer, "invalid markup byte");
        }
        advance_one(lexer);
        lexer->in_tag = true;
        lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_NAME;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_LESS_THAN,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }

    if (character >= 0x80U) {
        return fail_at_current(lexer, "invalid markup byte");
    }
    if (character == (unsigned char)'<') {
        return fail_at_current(lexer, "invalid markup tag transition");
    }
    if (character == (unsigned char)'>') {
        if (!tag_state_allows_end(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        lexer->in_tag = false;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_GREATER_THAN,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'/') {
        if (!tag_state_allows_slash(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME;
        } else {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_SELF_CLOSE_END;
        }
        set_token(token,
                  PBNFC_MARKUP_TOKEN_SLASH,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'=') {
        if (lexer->tag_state != PBNFC_MARKUP_TAG_EXPECT_EQUALS) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_VALUE;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_EQUALS,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'\'' ||
        character == (unsigned char)'"') {
        if (lexer->tag_state != PBNFC_MARKUP_TAG_EXPECT_VALUE) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        return read_string(lexer, token, location);
    }
    if (is_identifier_start(character)) {
        if (!tag_state_allows_identifier(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        do {
            advance_one(lexer);
        } while (lexer->offset < lexer->length &&
                 is_identifier_part(current_character(lexer)));
        if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_NAME;
        } else if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_CLOSE_NAME;
        } else if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_VALUE) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_VALUE;
        } else {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_EQUALS;
        }
        set_token(token,
                  PBNFC_MARKUP_TOKEN_IDENT,
                  location,
                  lexer->source + start,
                  lexer->offset - start);
        return true;
    }

    return fail_at_current(lexer, "invalid markup punctuation");
}

bool pbnfc_markup_lexer_failed(const PbnfcMarkupLexer *lexer)
{
    return lexer != NULL && lexer->failed;
}
