                free(tokens);
                (void)pbnfc_diagnostic_emit(diagnostics,
                                            "out of memory lexing input",
                                            NULL);
                return false;
            }
            tokens = next_tokens;
            capacity = next_capacity;
        }
        tokens[count] = token;
        ++count;
    }
    *tokens_out = tokens;
    *count_out = count;
    return true;
}

static void print_stats(const PbnfcRecognitionStats *stats)
{
    size_t worker_index;

    (void)fprintf(stdout,
                  " workers=%zu active_workers=%zu rounds=%zu tasks=",
                  stats->workers,
                  stats->active_workers,
                  stats->rounds);
    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        if (worker_index != 0U) {
            (void)fputc(',', stdout);
        }
        (void)fprintf(stdout, "%zu", stats->tasks[worker_index]);
    }
}

static int parse_options(int argc,
                         char **argv,
                         CliOptions *options,
                         const PbnfcDiagnosticContext *diagnostics)
{
    int index;

    for (index = 1; index < argc; ++index) {
        const char *argument = argv[index];

        if (strcmp(argument, "--grammar") == 0) {
            if (options->have_grammar) {
                return command_line_error(diagnostics, "duplicate option --grammar");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --grammar");
            }
            options->grammar_path = argv[++index];
            options->have_grammar = true;
        } else if (strcmp(argument, "--input") == 0) {
            if (options->have_input) {
                return command_line_error(diagnostics, "duplicate option --input");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --input");
            }
            options->input_path = argv[++index];
            options->have_input = true;
        } else if (strcmp(argument, "--start") == 0) {
            if (options->have_start) {
                return command_line_error(diagnostics, "duplicate option --start");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --start");
            }
            options->start_name = argv[++index];
            options->have_start = true;
        } else if (strcmp(argument, "--stats") == 0) {
            if (options->have_stats) {
                return command_line_error(diagnostics, "duplicate option --stats");
            }
            options->have_stats = true;
        } else if (is_option(argument)) {
            return command_line_error(diagnostics, "unknown option");
        } else {
            return command_line_error(diagnostics, "unexpected positional argument");
        }
    }

    if (!options->have_grammar) {
        return command_line_error(diagnostics, "missing required option --grammar");
    }
    if (!options->have_input) {
        return command_line_error(diagnostics, "missing required option --input");
    }

    return 0;
}

int main(int argc, char **argv)
{
    CliOptions options = {0};
    PbnfcDiagnosticContext diagnostics;
    char *grammar_source = NULL;
    char *input_source = NULL;
    size_t grammar_length = 0U;
    size_t input_length = 0U;
    PbnfcGrammar *grammar = NULL;
    PbnfcMarkupToken *tokens = NULL;
    size_t token_count = 0U;
    PbnfcRecognitionStats stats;
    PbnfcRecognitionResult result;
    int exit_code = 2;

    pbnfc_diagnostic_context_init(&diagnostics, stderr);

    (void)pthread_self();

    if (parse_options(argc, argv, &options, &diagnostics) != 0) {
        return 2;
    }

    if (!read_file(options.grammar_path,
                   "unable to read grammar file",
                   &grammar_source,
                   &grammar_length,
                   &diagnostics)) {
        goto cleanup;
    }
    if (!pbnfc_grammar_parse(grammar_source,
                             grammar_length,
                             &diagnostics,
                             &grammar) ||
        !pbnfc_grammar_validate(grammar, &diagnostics)) {
        goto cleanup;
    }
    if (!read_file(options.input_path,
                   "unable to read input file",
                   &input_source,
                   &input_length,
                   &diagnostics) ||
        !lex_input(input_source,
                   input_length,
                   &diagnostics,
                   &tokens,
                   &token_count)) {
        goto cleanup;
    }

    result = pbnfc_recognize_parallel_with_diagnostics(grammar,
                                                       tokens,
                                                       token_count,
                                                       options.start_name,
                                                       &diagnostics,
                                                       &stats);
    if (result == PBNFC_RECOGNITION_REJECTED) {
        exit_code = 1;
        goto cleanup;
    }
    if (result != PBNFC_RECOGNITION_ACCEPTED) {
        (void)pbnfc_diagnostic_emit(&diagnostics,
                                    "parallel recognizer failed",
                                    NULL);
        goto cleanup;
    }
    (void)fprintf(stdout, "ACCEPT tokens=%zu", token_count);
    if (options.have_stats) {
        print_stats(&stats);
    }
    (void)fputc('\n', stdout);
    exit_code = 0;

cleanup:
    free(tokens);
    pbnfc_grammar_free(grammar);
    free(input_source);
    free(grammar_source);
    return exit_code;
}

#include "markup_lexer.h"

static bool is_layout_space(unsigned char character)
{
    return character == (unsigned char)' ' ||
           character == (unsigned char)'\t' ||
           character == (unsigned char)'\v' ||
           character == (unsigned char)'\f' ||
           character == (unsigned char)'\r' ||
           character == (unsigned char)'\n';
}

static bool is_identifier_start(unsigned char character)
{
    return (character >= (unsigned char)'A' &&
            character <= (unsigned char)'Z') ||
           (character >= (unsigned char)'a' &&
            character <= (unsigned char)'z') ||
           character == (unsigned char)'_' ||
           character == (unsigned char)':';
}

static bool is_identifier_part(unsigned char character)
{
    return is_identifier_start(character) ||
           (character >= (unsigned char)'0' &&
            character <= (unsigned char)'9') ||
           character == (unsigned char)'.' ||
           character == (unsigned char)'-';
}

static unsigned char current_character(const PbnfcMarkupLexer *lexer)
{
    return (unsigned char)lexer->source[lexer->offset];
}

static void advance_one(PbnfcMarkupLexer *lexer)
{
    unsigned char character = current_character(lexer);

    ++lexer->offset;
    if (character == (unsigned char)'\n') {
        ++lexer->line;
        lexer->column = 1U;
    } else {
        ++lexer->column;
    }
}

static void skip_layout_space(PbnfcMarkupLexer *lexer)
{
    while (lexer->offset < lexer->length &&
           is_layout_space(current_character(lexer))) {
        advance_one(lexer);
    }
}

static bool text_has_nonspace(const PbnfcMarkupLexer *lexer, size_t start)
{
    size_t offset = start;

    while (offset < lexer->offset) {
        if (!is_layout_space((unsigned char)lexer->source[offset])) {
            return true;
        }
        ++offset;
    }
    return false;
}

static void set_token(PbnfcMarkupToken *token,
                      PbnfcMarkupTokenKind kind,
                      PbnfcLocation location,
                      const char *text,
                      size_t length)
{
    token->kind = kind;
    token->location = location;
    token->text = text;
    token->length = length;
}

static bool emit_error(PbnfcMarkupLexer *lexer,
                       const PbnfcLocation *location,
                       const char *detail)
{
    lexer->failed = true;
    if (lexer->diagnostics != NULL) {
        (void)pbnfc_diagnostic_emit(lexer->diagnostics, detail, location);
    }
    return false;
}

static bool fail_at_current(PbnfcMarkupLexer *lexer, const char *detail)
{
    PbnfcLocation location;

    location.byte_offset = lexer->offset;
    location.line = lexer->line;
    location.column = lexer->column;
    return emit_error(lexer, &location, detail);
}

static bool tag_state_allows_end(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE ||
           state == PBNFC_MARKUP_TAG_AFTER_CLOSE_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_SELF_CLOSE_END;
}

static bool tag_state_allows_slash(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_EXPECT_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE;
}

static bool tag_state_allows_identifier(PbnfcMarkupTagState state)
{
    return state == PBNFC_MARKUP_TAG_EXPECT_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME ||
           state == PBNFC_MARKUP_TAG_AFTER_NAME ||
           state == PBNFC_MARKUP_TAG_EXPECT_VALUE ||
           state == PBNFC_MARKUP_TAG_AFTER_VALUE;
}

static bool read_string(PbnfcMarkupLexer *lexer,
                        PbnfcMarkupToken *token,
                        PbnfcLocation location)
{
    const size_t start = lexer->offset;
    const unsigned char quote = current_character(lexer);

    advance_one(lexer);
    while (lexer->offset < lexer->length) {
        unsigned char character = current_character(lexer);

        if (character >= 0x80U) {
            return fail_at_current(lexer, "invalid markup byte");
        }
        if (character == (unsigned char)'\\') {
            advance_one(lexer);
            if (lexer->offset == lexer->length) {
                return emit_error(lexer,
                                  &location,
                                  "unterminated markup quoted value");
            }
            character = current_character(lexer);
            if (character != quote && character != (unsigned char)'\\') {
                return emit_error(lexer,
                                  &location,
                                  "invalid markup value escape");
            }
            advance_one(lexer);
            continue;
        }
        if (character == quote) {
            advance_one(lexer);
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_VALUE;
            set_token(token,
                      PBNFC_MARKUP_TOKEN_STRING,
                      location,
                      lexer->source + start,
                      lexer->offset - start);
            return true;
        }
        advance_one(lexer);
    }

    return emit_error(lexer,
                      &location,
                      "unterminated markup quoted value");
}

void pbnfc_markup_lexer_init(PbnfcMarkupLexer *lexer,
                             const char *source,
                             size_t length,
                             const PbnfcDiagnosticContext *diagnostics)
{
    if (lexer == NULL) {
        return;
    }
    lexer->source = source;
    lexer->length = length;
    lexer->offset = 0U;
    lexer->line = 1U;
    lexer->column = 1U;
    lexer->in_tag = false;
    lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_NAME;
    lexer->diagnostics = diagnostics;
    lexer->failed = false;
}

bool pbnfc_markup_lexer_next(PbnfcMarkupLexer *lexer,
                             PbnfcMarkupToken *token)
{
    PbnfcLocation location;
    size_t start;
    unsigned char character;

    if (lexer == NULL || token == NULL || lexer->failed) {
        return false;
    }
    if (lexer->source == NULL && lexer->length != 0U) {
        return fail_at_current(lexer, "markup source is unavailable");
    }

    if (lexer->in_tag) {
        skip_layout_space(lexer);
    } else {
        for (;;) {
            start = lexer->offset;
            location.byte_offset = start;
            location.line = lexer->line;
            location.column = lexer->column;

            while (lexer->offset < lexer->length &&
                   current_character(lexer) != (unsigned char)'<') {
                advance_one(lexer);
            }
            if (lexer->offset != start) {
                if (text_has_nonspace(lexer, start)) {
                    set_token(token,
                              PBNFC_MARKUP_TOKEN_TEXT,
                              location,
                              lexer->source + start,
                              lexer->offset - start);
                    return true;
                }
                continue;
            }
            break;
        }
    }

    if (lexer->offset == lexer->length) {
        if (lexer->in_tag) {
            return fail_at_current(lexer, "unterminated markup tag");
        }
        location.byte_offset = lexer->offset;
        location.line = lexer->line;
        location.column = lexer->column;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_EOF,
                  location,
                  lexer->source == NULL ? NULL : lexer->source + lexer->offset,
                  0U);
        return true;
    }

    start = lexer->offset;
    location.byte_offset = start;
    location.line = lexer->line;
    location.column = lexer->column;
    character = current_character(lexer);

    if (!lexer->in_tag) {
        if (character != (unsigned char)'<') {
            return fail_at_current(lexer, "invalid markup byte");
        }
        advance_one(lexer);
        lexer->in_tag = true;
        lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_NAME;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_LESS_THAN,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }

    if (character >= 0x80U) {
        return fail_at_current(lexer, "invalid markup byte");
    }
    if (character == (unsigned char)'<') {
        return fail_at_current(lexer, "invalid markup tag transition");
    }
    if (character == (unsigned char)'>') {
        if (!tag_state_allows_end(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        lexer->in_tag = false;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_GREATER_THAN,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'/') {
        if (!tag_state_allows_slash(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME;
        } else {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_SELF_CLOSE_END;
        }
        set_token(token,
                  PBNFC_MARKUP_TOKEN_SLASH,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'=') {
        if (lexer->tag_state != PBNFC_MARKUP_TAG_EXPECT_EQUALS) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        advance_one(lexer);
        lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_VALUE;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_EQUALS,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'\'' ||
        character == (unsigned char)'"') {
        if (lexer->tag_state != PBNFC_MARKUP_TAG_EXPECT_VALUE) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        return read_string(lexer, token, location);
    }
    if (is_identifier_start(character)) {
        if (!tag_state_allows_identifier(lexer->tag_state)) {
            return fail_at_current(lexer, "invalid markup tag transition");
        }
        do {
            advance_one(lexer);
        } while (lexer->offset < lexer->length &&
                 is_identifier_part(current_character(lexer)));
        if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_NAME;
        } else if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_CLOSE_NAME) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_CLOSE_NAME;
        } else if (lexer->tag_state == PBNFC_MARKUP_TAG_EXPECT_VALUE) {
            lexer->tag_state = PBNFC_MARKUP_TAG_AFTER_VALUE;
        } else {
            lexer->tag_state = PBNFC_MARKUP_TAG_EXPECT_EQUALS;
        }
        set_token(token,
                  PBNFC_MARKUP_TOKEN_IDENT,
                  location,
                  lexer->source + start,
                  lexer->offset - start);
        return true;
    }

    return fail_at_current(lexer, "invalid markup punctuation");
}

bool pbnfc_markup_lexer_failed(const PbnfcMarkupLexer *lexer)
{
    return lexer != NULL && lexer->failed;
}

const char *pbnfc_markup_token_kind_name(PbnfcMarkupTokenKind kind)
{
    switch (kind) {
    case PBNFC_MARKUP_TOKEN_EOF:
        return "EOF";
    case PBNFC_MARKUP_TOKEN_LESS_THAN:
        return "<";
    case PBNFC_MARKUP_TOKEN_GREATER_THAN:
        return ">";
    case PBNFC_MARKUP_TOKEN_SLASH:
        return "/";
    case PBNFC_MARKUP_TOKEN_EQUALS:
        return "=";
    case PBNFC_MARKUP_TOKEN_IDENT:
        return "IDENT";
    case PBNFC_MARKUP_TOKEN_STRING:
        return "STRING";
    case PBNFC_MARKUP_TOKEN_TEXT:
        return "TEXT";
    }
    return "unknown";
}

#include "recognizer.h"

#include "chart.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static bool names_equal(const char *left, const char *right)
{
    return left != NULL && right != NULL && strcmp(left, right) == 0;
}

static bool production_index(const PbnfcGrammar *grammar,
                             const char *name,
                             size_t *index_out)
{
    size_t index;

    for (index = 0U; index < grammar->production_count; ++index) {
        if (names_equal(grammar->productions[index].name, name)) {
            if (index_out != NULL) {
                *index_out = index;
            }
            return true;
        }
    }
    return false;
}

static bool text_matches(const PbnfcGrammarSymbol *symbol,
                         const PbnfcMarkupToken *token)
{
    const char *kind_name;
    size_t name_length;

    if (symbol == NULL || token == NULL || symbol->name == NULL) {
        return false;
    }
    if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_TERMINAL) {
        name_length = strlen(symbol->name);
        return token->length == name_length &&
               (name_length == 0U ||
                memcmp(token->text, symbol->name, name_length) == 0);
    }
    if (symbol->kind != PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE) {
        return false;
    }
    kind_name = pbnfc_markup_token_kind_name(token->kind);
    return names_equal(symbol->name, kind_name);
}

static bool insert_item(PbnfcChart *chart,
                        size_t production,
                        size_t alternative,
                        size_t dot,
                        size_t origin,
                        size_t position)
{
    PbnfcChartItem item = pbnfc_chart_item_make(production,
                                                alternative,
                                                dot,
                                                origin,
                                                position);

    return pbnfc_chart_insert(chart, &item) != PBNFC_CHART_INSERT_ERROR;
}

static bool predict(PbnfcChart *chart,
                    const PbnfcGrammar *grammar,
                    const char *name,
                    size_t position)
{
    size_t production;
    size_t alternative;

    if (!production_index(grammar, name, &production)) {
        return false;
    }
    for (alternative = 0U;
         alternative < grammar->productions[production].alternative_count;
         ++alternative) {
        if (!insert_item(chart, production, alternative, 0U,
                         position, position)) {
            return false;
        }
    }
    return true;
}

static bool complete(PbnfcChart *chart,
                     const PbnfcGrammar *grammar,
                     const PbnfcChartItem *completed,
                     size_t position)
{
    const PbnfcGrammarProduction *completed_production;
    const PbnfcChartSet *origin_set;
    size_t source_index;
    size_t completed_production_index = completed->production;

    completed_production =
        &grammar->productions[completed_production_index];
    origin_set = pbnfc_chart_set_const(chart, completed->origin);
    if (origin_set == NULL) {
        return false;
    }

    /* The origin set can be the current set for an epsilon completion. */
    for (source_index = 0U;
         source_index < pbnfc_chart_set_size(origin_set);
         ++source_index) {
        PbnfcChartItem source_item = *pbnfc_chart_set_at(origin_set,
                                                         source_index);
        const PbnfcGrammarProduction *source_production =
            &grammar->productions[source_item.production];
        const PbnfcGrammarAlternative *source_alternative;
        const PbnfcGrammarSymbol *symbol;

        if (source_item.dot >= source_production->alternatives[
                                    source_item.alternative].symbol_count) {
            continue;
        }
        source_alternative =
            &source_production->alternatives[source_item.alternative];
        symbol = &source_alternative->symbols[source_item.dot];
        if (symbol->kind != PBNFC_GRAMMAR_SYMBOL_NONTERMINAL ||
            !names_equal(symbol->name, completed_production->name)) {
            continue;
        }
        if (!insert_item(chart,
                         source_item.production,
                         source_item.alternative,
                         source_item.dot + 1U,
                         source_item.origin,
                         position)) {
            return false;
        }
    }
    return true;
}

static bool close_position(PbnfcChart *chart,
                           const PbnfcGrammar *grammar,
                           size_t position)
{
    PbnfcChartSet *set = pbnfc_chart_set(chart, position);
    size_t item_index;

    if (set == NULL) {
        return false;
    }
    for (item_index = 0U;
         item_index < pbnfc_chart_set_size(set);
         ++item_index) {
        PbnfcChartItem item = *pbnfc_chart_set_at(set, item_index);
        const PbnfcGrammarProduction *production =
            &grammar->productions[item.production];
        const PbnfcGrammarAlternative *alternative =
            &production->alternatives[item.alternative];

        if (item.dot == alternative->symbol_count) {
            if (!complete(chart, grammar, &item, position)) {
                return false;
            }
        } else {
            const PbnfcGrammarSymbol *symbol =
                &alternative->symbols[item.dot];

            if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_NONTERMINAL &&
                !predict(chart, grammar, symbol->name, position)) {
                return false;
            }
        }
    }
    return true;
}

static bool scan_position(PbnfcChart *chart,
                          const PbnfcGrammar *grammar,
                          const PbnfcMarkupToken *tokens,
                          size_t token_count,
                          size_t position)
{
    const PbnfcChartSet *set;
    const PbnfcMarkupToken *token;
    size_t item_index;

    if (position >= token_count) {
        return true;
    }
    set = pbnfc_chart_set_const(chart, position);
    token = &tokens[position];
    if (set == NULL) {
        return false;
    }
    for (item_index = 0U;
         item_index < pbnfc_chart_set_size(set);
         ++item_index) {
        PbnfcChartItem item = *pbnfc_chart_set_at(set, item_index);
        const PbnfcGrammarProduction *production =
            &grammar->productions[item.production];
        const PbnfcGrammarAlternative *alternative =
            &production->alternatives[item.alternative];
        const PbnfcGrammarSymbol *symbol;

        if (item.dot >= alternative->symbol_count) {
            continue;
        }
        symbol = &alternative->symbols[item.dot];
        if ((symbol->kind == PBNFC_GRAMMAR_SYMBOL_TERMINAL ||
             symbol->kind == PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE) &&
            text_matches(symbol, token) &&
            !insert_item(chart,
                         item.production,
                         item.alternative,
                         item.dot + 1U,
                         item.origin,
                         position + 1U)) {
            return false;
        }
    }
    return true;
}

static bool has_accepting_item(const PbnfcChart *chart,
                               const PbnfcGrammar *grammar,
                               size_t start_production,
                               size_t final_position)
{
    const PbnfcChartSet *set =
        pbnfc_chart_set_const(chart, final_position);
    size_t item_index;

    if (set == NULL) {
        return false;
    }
    for (item_index = 0U;
         item_index < pbnfc_chart_set_size(set);
         ++item_index) {
        const PbnfcChartItem *item = pbnfc_chart_set_at(set, item_index);
        const PbnfcGrammarProduction *production;
        const PbnfcGrammarAlternative *alternative;

        if (item == NULL || item->production != start_production ||
            item->origin != 0U) {
            continue;
        }
        production = &grammar->productions[item->production];
        alternative = &production->alternatives[item->alternative];
        if (item->dot == alternative->symbol_count &&
            item->position == final_position) {
            return true;
        }
    }
    return false;
}

static bool append_expected_text(char **text,
                                 size_t *length,
                                 size_t *capacity,
                                 const char *addition)
{
    size_t addition_length;
    size_t needed;
    size_t next_capacity;
    char *next_text;

    if (text == NULL || length == NULL || capacity == NULL || addition == NULL) {
        return false;
    }
    addition_length = strlen(addition);
    if (*length > SIZE_MAX - addition_length - 1U) {
        return false;
    }
    needed = *length + addition_length + 1U;
    if (needed > *capacity) {
        next_capacity = *capacity == 0U ? 32U : *capacity;
        while (next_capacity < needed) {
            if (next_capacity > SIZE_MAX / 2U) {
                next_capacity = needed;
                break;
            }
            next_capacity *= 2U;
        }
        next_text = (char *)realloc(*text, next_capacity);
        if (next_text == NULL) {
            return false;
        }
        *text = next_text;
        *capacity = next_capacity;
    }
    (void)memcpy(*text + *length, addition, addition_length);
    *length += addition_length;
    (*text)[*length] = '\0';
    return true;
}

static bool expected_symbol_equal(const PbnfcGrammarSymbol *left,
                                  const PbnfcGrammarSymbol *right)
{
    return left != NULL && right != NULL && left->kind == right->kind &&
           names_equal(left->name, right->name);
}

static bool expected_symbol_seen(const PbnfcChartSet *set,
                                 size_t item_index,
                                 const PbnfcGrammar *grammar,
                                 const PbnfcGrammarSymbol *symbol)
{
    size_t prior_index;

    for (prior_index = 0U; prior_index < item_index; ++prior_index) {
        const PbnfcChartItem *prior_item =
            pbnfc_chart_set_at(set, prior_index);
        const PbnfcGrammarProduction *prior_production;
        const PbnfcGrammarAlternative *prior_alternative;
        const PbnfcGrammarSymbol *prior_symbol;

        if (prior_item == NULL) {
            continue;
        }
        prior_production = &grammar->productions[prior_item->production];
        prior_alternative =
            &prior_production->alternatives[prior_item->alternative];
        if (prior_item->dot >= prior_alternative->symbol_count) {
            continue;
        }
        prior_symbol = &prior_alternative->symbols[prior_item->dot];
        if (expected_symbol_equal(prior_symbol, symbol)) {
            return true;
        }
    }
    return false;
}

static bool append_expected_symbol(char **text,
                                   size_t *length,
                                   size_t *capacity,
                                   const PbnfcGrammarSymbol *symbol)
{
    const char *prefix = "";
    const char *suffix = "";

    if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_TERMINAL) {
        prefix = "'";
        suffix = "'";
    } else if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE) {
        prefix = "$";
    }
    return append_expected_text(text, length, capacity, prefix) &&
           append_expected_text(text, length, capacity, symbol->name) &&
           append_expected_text(text, length, capacity, suffix);
}

static char *expected_detail(const PbnfcChartSet *set,
                             const PbnfcGrammar *grammar)
{
    char *text = NULL;
    size_t length = 0U;
    size_t capacity = 0U;
    size_t item_index;

    if (set != NULL) {
        for (item_index = 0U;
             item_index < pbnfc_chart_set_size(set);
             ++item_index) {
            const PbnfcChartItem *item =
                pbnfc_chart_set_at(set, item_index);
            const PbnfcGrammarProduction *production;
            const PbnfcGrammarAlternative *alternative;
            const PbnfcGrammarSymbol *symbol;

            if (item == NULL) {
                continue;
            }
            production = &grammar->productions[item->production];
            alternative = &production->alternatives[item->alternative];
            if (item->dot >= alternative->symbol_count) {
                continue;
            }
            symbol = &alternative->symbols[item->dot];
            if (expected_symbol_seen(set, item_index, grammar, symbol)) {
                continue;
            }
            if (length != 0U &&
                !append_expected_text(&text, &length, &capacity, " | ")) {
                free(text);
                return NULL;
            }
            if (!append_expected_symbol(&text,
                                        &length,
                                        &capacity,
                                        symbol)) {
                free(text);
                return NULL;
            }
        }
    }
    if (length == 0U &&
        !append_expected_text(&text, &length, &capacity, "end of input")) {
        free(text);
        return NULL;
    }
    return text;
}

static PbnfcLocation location_after_token(const PbnfcMarkupToken *token)
{
    PbnfcLocation location;
    size_t index;

    location = token->location;
    if (location.byte_offset > SIZE_MAX - token->length) {
        location.byte_offset = SIZE_MAX;
    } else {
        location.byte_offset += token->length;
    }
    for (index = 0U; index < token->length; ++index) {
        if (token->text[index] == '\n') {
            ++location.line;
            location.column = 1U;
        } else if (location.column != SIZE_MAX) {
            ++location.column;
        }
    }
    return location;
}

static PbnfcLocation eof_location(const PbnfcMarkupToken *tokens,
                                  size_t token_count)
{
    PbnfcLocation location;

    if (token_count == 0U) {
        location.byte_offset = 0U;
        location.line = 1U;
        location.column = 1U;
        return location;
    }
    return location_after_token(&tokens[token_count - 1U]);
}

